export function isValidWord(word: string): boolean {
  if (!word) return false;
  return DICTIONARY_SET.has(word.trim().toUpperCase());
}

export function isOneLetterDiff(a: string, b: string): boolean {
  if (!a || !b || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) {
      diff++;
      if (diff > 1) return false;
    }
  }
  return diff === 1;
}

export function getChangedIndex(a: string, b: string): number {
  if (!a || !b || a.length !== b.length) return -1;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return i;
  }
  return -1;
}

/**
 * Calculates the shortest path between startWord and targetWord using Breadth-First Search (BFS).
 * Dynamically computes optimal path without relying on hardcoded numbers.
 */
export function findShortestPath(
  startWord: string,
  targetWord: string,
  dictionary: Set<string> = DICTIONARY_SET,
  excludedWords: Set<string> = new Set()
): string[] | null {
  startWord = startWord.trim().toUpperCase();
  targetWord = targetWord.trim().toUpperCase();
  if (startWord === targetWord) return [startWord];
  if (startWord.length !== targetWord.length) return null;

  const wordLen = startWord.length;
  const queue: string[] = [startWord];
  const parent = new Map<string, string>();
  const visited = new Set<string>([startWord, ...excludedWords]);
  visited.delete(targetWord); // ensure target is reachable

  let head = 0;
  let found = false;

  while (head < queue.length) {
    const curr = queue[head++];
    if (curr === targetWord) {
      found = true;
      break;
    }

    for (let i = 0; i < wordLen; i++) {
      const origChar = curr[i];
      for (let c = 65; c <= 90; c++) {
        const ch = String.fromCharCode(c);
        if (ch === origChar) continue;
        const next = curr.substring(0, i) + ch + curr.substring(i + 1);
        if (dictionary.has(next) && !visited.has(next)) {
          visited.add(next);
          parent.set(next, curr);
          queue.push(next);
          if (next === targetWord) {
            found = true;
            break;
          }
        }
      }
      if (found) break;
    }
  }

  if (!found) return null;

  const path: string[] = [];
  let curr: string | undefined = targetWord;
  while (curr) {
    path.unshift(curr);
    curr = parent.get(curr);
  }
  return path;
}

/**
 * Intelligent hint generator:
 * Runs BFS from currentWord to targetWord excluding already-used words,
 * guaranteeing the hint points along a valid shortest route from the player's current position.
 */
export function findNextHintWord(
  currentWord: string,
  targetWord: string,
  usedWords: Set<string> = new Set()
): string | null {
  currentWord = currentWord.trim().toUpperCase();
  targetWord = targetWord.trim().toUpperCase();
  if (currentWord === targetWord) return null;

  const path = findShortestPath(currentWord, targetWord, DICTIONARY_SET, usedWords);
  if (!path || path.length < 2) return null;
  return path[1];
}

/**
 * Deterministic UTC date-based puzzle selector.
 * Returns the daily challenge for that date and difficulty worldwide.
 */
export function getDailyPuzzle(
  date: Date = new Date(),
  difficulty: 'easy' | 'medium' | 'hard' = 'easy'
): WordLadderPuzzle {
  const year = date.getUTCFullYear();
  const startOfYear = Date.UTC(year, 0, 1);
  const currentUtc = Date.UTC(year, date.getUTCMonth(), date.getUTCDate());
  const dayOfYear = Math.floor((currentUtc - startOfYear) / (24 * 60 * 60 * 1000));

  let pool = PUZZLES_EASY;
  let offset = 0;
  if (difficulty === 'medium') {
    pool = PUZZLES_MEDIUM;
    offset = 11;
  } else if (difficulty === 'hard') {
    pool = PUZZLES_HARD;
    offset = 23;
  }

  const idx = Math.abs(dayOfYear + offset) % pool.length;
  const puzzle = pool[idx];

  return {
    ...puzzle,
    id: `daily-${difficulty}-${year}-${dayOfYear}`
  };
}

/**
 * Calculates Medal based on actual moves vs BFS shortest path, taking hint penalties into account.
 * - Gold: Solved in minimum possible steps.
 * - Silver: Solved in exactly 1 extra step.
 * - Bronze: Solved in exactly 2 extra steps.
 * - None: Solved in >2 extra steps.
 */
export function calculateMedal(
  moves: number,
  minMoves: number,
  hintsUsed: number = 0
): { medal: 'gold' | 'silver' | 'bronze' | 'none'; title: string; desc: string; icon: string } {
  const effectiveSteps = moves + hintsUsed * 1;

  if (effectiveSteps === minMoves) {
    return {
      medal: 'gold',
      title: 'Gold Medal Winner!',
      desc: `Solved in the absolute shortest path of ${minMoves} steps! Perfect performance.`,
      icon: '🥇'
    };
  }

  if (effectiveSteps === minMoves + 1) {
    return {
      medal: 'silver',
      title: 'Silver Medal Winner!',
      desc: `Solved in ${effectiveSteps} effective steps (only 1 step over shortest ${minMoves})!`,
      icon: '🥈'
    };
  }

  if (effectiveSteps === minMoves + 2) {
    return {
      medal: 'bronze',
      title: 'Bronze Medal Winner!',
      desc: `Solved in ${effectiveSteps} effective steps (only 2 steps over shortest ${minMoves})!`,
      icon: '🥉'
    };
  }

  return {
    medal: 'none',
    title: 'Puzzle Completed!',
    desc: `Great job completing the word ladder in ${moves} moves.`,
    icon: '🏅'
  };
}
